const Footer = () => {
  return (
    <div className="py-8 px-4">
      <h3>Socials</h3>
      <div>
        <svg width="100" height="100">
          <circle
            cx="50"
            cy="50"
            r="40"
            stroke="green"
            stroke-width="4"
            fill="yellow"
          />
        </svg>
      </div>
      <h3>© 2025 Mateo Hernandez. All Rights Reserved.</h3>
    </div>
  );
};

export default Footer;
